	protected Distributor read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Distributor" );

		Distributor entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Distributor with primary key" );
		msg.append( distributorId );
		
		DistributorFetchOneSummary fetchOneSummary = new DistributorFetchOneSummary( distributorId );

		try {
			entity = DistributorService.getDistributorInstance().getDistributor( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Distributor " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Distributor.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Distributor." );

		StringBuilder msg = new StringBuilder( "Failed to update a Distributor : " );        
		Distributor entity = read();
		UpdateDistributorCommand command = generateUpdateCommand();
		command.setDistributorId(entity.getDistributorId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Distributor." );

			// for use later on...
			distributorId = entity.getDistributorId();

			DistributorService proxy = DistributorService.getDistributorInstance();  

			proxy.updateDistributor( command ).get();

			LOGGER.info( "-- Successfully saved Distributor - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + distributorId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Distributor.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Distributor." );

		Distributor entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Distributor with id " + distributorId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Distributor with id " + distributorId );

			throw e;
		}

		try{
			DistributorService.getDistributorInstance().delete( new DeleteDistributorCommand( entity.getDistributorId() ) ).get();
			LOGGER.info( "-- Successfully deleted Distributor with id " + distributorId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Distributor with id " + distributorId );

			throw e;
		}
	}

	/**
	 * get all Distributors.
	 */
	protected List<Distributor> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Distributors:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Distributor : " );        
		List<Distributor> collection  = new ArrayList<>();

		try {
			// call the static get method on the DistributorService
			collection = DistributorService.getDistributorInstance().getAllDistributor();
			assertNotNull( collection, "An Empty collection of Distributor was incorrectly returned.");
			
			// Now print out the values
			Distributor entity = null;            
			Iterator<Distributor> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getDistributorId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

